import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp', 'pdf']
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB
UPLOAD_DIR = '/tmp/conversions'

os.makedirs(UPLOAD_DIR, exist_ok=True)

def sanitize_filename(filename):
    """Remove path traversal attempts"""
    basename = os.path.basename(filename)
    # Strip null bytes
    basename = basename.replace('\x00', '')
    return basename

def validate_format(fmt):
    """Check output format is allowed"""
    return fmt.lower() in ALLOWED_FORMATS

@app.route('/api/convert', methods=['POST'])
def convert_file():
    """Convert uploaded file to specified format using ImageMagick"""
    if 'file' not in request.files:
        abort(400, 'No file provided')

    uploaded = request.files['file']
    output_format = request.form.get('format', 'png')
    density = request.form.get('density', '150')
    resize = request.form.get('resize', '')

    if not validate_format(output_format):
        abort(400, f'Invalid format: {output_format}')

    if uploaded.content_length and uploaded.content_length > MAX_FILE_SIZE:
        abort(413, 'File too large')

    safe_name = sanitize_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, f'input_{safe_name}')
    output_path = os.path.join(UPLOAD_DIR, f'output_{safe_name}.{output_format}')

    uploaded.save(input_path)

    try:
        cmd = ['convert', input_path, '-density', density]

        if resize:
            # Resize parameter: e.g., "800x600", "50%"
            cmd.extend(['-resize', resize])

        cmd.extend(['-quality', '85', output_path])

        result = subprocess.run(
            cmd,
            capture_output=True,
            timeout=30,
            env={**os.environ, 'MAGICK_TMPDIR': UPLOAD_DIR}
        )

        if result.returncode != 0:
            app.logger.error(f'Conversion failed: {result.stderr.decode()}')
            abort(500, 'Conversion failed')

        with open(output_path, 'rb') as f:
            data = f.read()

        return data, 200, {'Content-Type': f'image/{output_format}'}

    except subprocess.TimeoutExpired:
        abort(504, 'Conversion timed out')
    finally:
        for p in [input_path, output_path]:
            if os.path.exists(p):
                os.unlink(p)

@app.route('/api/metadata', methods=['POST'])
def get_metadata():
    """Extract metadata from uploaded image"""
    if 'file' not in request.files:
        abort(400, 'No file provided')

    uploaded = request.files['file']
    safe_name = sanitize_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, f'meta_{safe_name}')
    uploaded.save(input_path)

    try:
        result = subprocess.run(
            ['identify', '-verbose', input_path],
            capture_output=True,
            timeout=10
        )

        if result.returncode != 0:
            abort(500, 'Could not read metadata')

        return jsonify({'metadata': result.stdout.decode(errors='replace')})
    except subprocess.TimeoutExpired:
        abort(504, 'Metadata extraction timed out')
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/health')
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
